-- 4. 性能索引优化 (Indexes)
--------------------------------------------------------------------------------

-- 4.1 搜索优化 (pg_trgm)
create index if not exists idx_works_title_trgm on works using gin (title gin_trgm_ops);
create index if not exists idx_works_author_trgm on works using gin (author_name gin_trgm_ops);

-- 4.2 标签关联查询优化 (高频JOIN)
create index if not exists idx_work_tags_tag_id on work_tags(tag_id);
create index if not exists idx_work_tags_work_id on work_tags(work_id);
create index if not exists idx_tags_category on tags(category);

-- 4.3 电台查询优化 (时间倒序 & 用户相关)
create index if not exists idx_radio_created_at on radio_messages(created_at desc);
create index if not exists idx_radio_reactions_message_id on radio_reactions(message_id);
create index if not exists idx_radio_reactions_user_id on radio_reactions(user_id);

-- 4.4 收藏夹查询优化
create index if not exists idx_favorite_folders_user_id on favorite_folders(user_id);
create index if not exists idx_folder_entries_work_id on folder_entries(work_id);
create index if not exists idx_folder_entries_folder_id on folder_entries(folder_id);


--------------------------------------------------------------------------------
-- 5. 安全策略 (RLS Policies)
--------------------------------------------------------------------------------

-- 启用 RLS
alter table invite_codes enable row level security;
alter table profiles enable row level security;
alter table works enable row level security;
alter table tags enable row level security;
alter table work_tags enable row level security;
alter table radio_messages enable row level security;
alter table radio_reactions enable row level security; -- 补上这个漏网之鱼
alter table favorite_folders enable row level security;
alter table folder_entries enable row level security; -- 补上这个漏网之鱼

-- 5.1 Invite Codes 策略
create policy "Allow public read invite codes" on invite_codes for select using (true);

-- 5.2 Profiles 策略
create policy "Profiles are public" on profiles for select using (true);
create policy "Users can update own profile" on profiles for update using (auth.uid() = id);

-- 5.3 Works 策略
create policy "Works are public" on works for select using (true);
create policy "Users can insert works" on works for insert with check (auth.role() = 'authenticated');
create policy "Authenticated users can update works" on works for update
  using (auth.role() = 'authenticated')
  with check (auth.role() = 'authenticated');
-- 允许作者删除自己的作品 (逻辑保留，按需调整)
create policy "Users can delete own works" on works for delete using (auth.uid() = submitter_id);

-- 5.4 Tags 策略
create policy "Public read tags" on tags for select using (true);
create policy "Authenticated insert tags" on tags for insert with check (auth.role() = 'authenticated');

-- 5.5 Work Tags 策略
create policy "Public read work_tags" on work_tags for select using (true);
create policy "Authenticated insert work_tags" on work_tags for insert with check (auth.role() = 'authenticated');
create policy "Authenticated delete work_tags" on work_tags for delete using (auth.role() = 'authenticated');

-- 5.6 Radio 策略
create policy "Messages are public" on radio_messages for select using (true);
create policy "Users can insert messages" on radio_messages for insert with check (auth.role() = 'authenticated');

-- 5.7 Reactions 策略
create policy "Reactions are public" on radio_reactions for select using (true);
create policy "Users can insert reactions" on radio_reactions for insert with check (auth.role() = 'authenticated');
create policy "Users can delete own reactions" on radio_reactions for delete using (auth.uid() = user_id);

-- 5.8 Favorites 策略 (隐私保护：仅自己可见)
create policy "Users can see own favorites" on favorite_folders for select using (auth.uid() = user_id);
create policy "Users can manage own favorites" on favorite_folders for all using (auth.uid() = user_id);

create policy "Users can see own folder entries" on folder_entries for select using (
  exists (select 1 from favorite_folders where id = folder_id and user_id = auth.uid())
);
create policy "Users can manage own folder entries" on folder_entries for all using (
  exists (select 1 from favorite_folders where id = folder_id and user_id = auth.uid())
);


